import { Controller, Get } from '@nestjs/common';
import type { AdminCourse } from '@coursecraft/shared';
import { Roles } from '../auth/auth.decorators.js';
import { PrismaService } from '../prisma/prisma.service.js';

/** The admin's view of all courses, in every status (#29). Public lists only show published ones. */
@Controller('admin/courses')
@Roles('ADMIN')
export class AdminCoursesController {
  constructor(private readonly prisma: PrismaService) {}

  /** Newest activity first. Bounded: a course is generated by an admin, minutes at a time. */
  @Get()
  async list(): Promise<AdminCourse[]> {
    const rows = await this.prisma.course.findMany({
      orderBy: [{ updatedAt: 'desc' }, { id: 'asc' }],
      take: 500,
      select: {
        id: true,
        slug: true,
        title: true,
        status: true,
        level: true,
        thumbnailUrl: true,
        createdAt: true,
        updatedAt: true,
        domain: { select: { id: true, name: true, slug: true } },
        modules: { select: { _count: { select: { lessons: true } } } },
        jobs: {
          orderBy: { createdAt: 'desc' },
          take: 1,
          select: { id: true, status: true, stage: true, progress: true, error: true },
        },
      },
    });
    return rows.map(({ modules, jobs, createdAt, updatedAt, ...course }) => ({
      ...course,
      moduleCount: modules.length,
      lessonCount: modules.reduce((sum, m) => sum + m._count.lessons, 0),
      createdAt: createdAt.toISOString(),
      updatedAt: updatedAt.toISOString(),
      latestJob: jobs[0] ?? null,
    }));
  }
}
